/// A fully timed episode, generated by tools/build_episode.py.
///
/// The voice stem is the master clock: every scene, segment and line carries
/// absolute start/end times on that stem.
class Episode {
  final String bookId;
  final String id;
  final int number;
  final String title;
  final String bookTitle;
  final String bookSubtitle;
  final String author;
  final String genre;
  final String location;
  final String note;
  final Duration duration;
  final String voiceAsset;
  final String musicAsset;
  final String sfxAsset;
  final Map<String, Speaker> speakers;
  final List<Scene> scenes;
  final List<Segment> segments;

  const Episode({
    required this.bookId,
    required this.id,
    required this.number,
    required this.title,
    required this.bookTitle,
    required this.bookSubtitle,
    required this.author,
    required this.genre,
    required this.location,
    required this.note,
    required this.duration,
    required this.voiceAsset,
    required this.musicAsset,
    required this.sfxAsset,
    required this.speakers,
    required this.scenes,
    required this.segments,
  });

  factory Episode.fromJson(Map<String, dynamic> json) {
    final audio = json['audio'] as Map<String, dynamic>;
    final speakers = (json['speakers'] as Map<String, dynamic>).map(
      (k, v) => MapEntry(k, Speaker.fromJson(k, v as Map<String, dynamic>)),
    );
    return Episode(
      bookId: json['bookId'] as String,
      id: json['id'] as String,
      number: json['number'] as int,
      title: json['title'] as String,
      bookTitle: json['bookTitle'] as String? ?? '',
      bookSubtitle: json['bookSubtitle'] as String? ?? '',
      author: json['author'] as String? ?? '',
      genre: json['genre'] as String? ?? '',
      location: json['location'] as String? ?? '',
      note: json['note'] as String? ?? '',
      duration: Duration(milliseconds: json['durationMs'] as int),
      voiceAsset: audio['voice'] as String,
      musicAsset: audio['music'] as String,
      sfxAsset: audio['sfx'] as String,
      speakers: speakers,
      scenes: (json['scenes'] as List).map((s) => Scene.fromJson(s as Map<String, dynamic>)).toList(),
      segments:
          (json['segments'] as List).map((s) => Segment.fromJson(s as Map<String, dynamic>)).toList(),
    );
  }

  String get progressKey => '$bookId/$id';

  /// Index of the scene showing at [position].
  int sceneIndexAt(Duration position) {
    for (var i = scenes.length - 1; i >= 0; i--) {
      if (position >= scenes[i].start) return i;
    }
    return 0;
  }

  /// The segment to display at [position]: the latest one that has started
  /// within the current scene, or the scene's first segment before that.
  Segment? segmentAt(Duration position) {
    final scene = scenes[sceneIndexAt(position)];
    final inScene = segments.where((s) => s.scene == scene.number).toList();
    if (inScene.isEmpty) return null;
    Segment current = inScene.first;
    for (final s in inScene) {
      if (position >= s.start) current = s;
    }
    return current;
  }

  /// The segment whose audio is actually sounding at [position], if any.
  Segment? speakingAt(Duration position) {
    for (final s in segments) {
      if (position >= s.start && position < s.end) return s;
    }
    return null;
  }

  List<Segment> segmentsOfScene(int sceneNumber) =>
      segments.where((s) => s.scene == sceneNumber).toList();
}

class Speaker {
  final String id;
  final String name;
  final String description;

  const Speaker({required this.id, required this.name, required this.description});

  factory Speaker.fromJson(String id, Map<String, dynamic> json) => Speaker(
        id: id,
        name: json['name'] as String,
        description: json['description'] as String? ?? '',
      );
}

class Scene {
  final int number;
  final String title;
  final String layout;
  final String image;
  final Duration start;
  final Duration end;
  final List<String> music;
  final List<String> sfx;

  const Scene({
    required this.number,
    required this.title,
    required this.layout,
    required this.image,
    required this.start,
    required this.end,
    required this.music,
    required this.sfx,
  });

  bool get isClosing => layout == 'closing';

  factory Scene.fromJson(Map<String, dynamic> json) => Scene(
        number: json['number'] as int,
        title: json['title'] as String,
        layout: json['layout'] as String? ?? 'plate',
        image: json['image'] as String,
        start: Duration(milliseconds: json['startMs'] as int),
        end: Duration(milliseconds: json['endMs'] as int),
        music: List<String>.from(json['music'] as List? ?? const []),
        sfx: List<String>.from(json['sfx'] as List? ?? const []),
      );
}

class Segment {
  final String id;
  final int scene;
  final String speakerId;
  final String speakerName;
  final String direction;
  final String text;
  final String? trailingText;
  final Duration start;
  final Duration end;
  final String audioSource;
  final Duration sourceStart;
  final Duration sourceEnd;
  final List<Line> lines;

  const Segment({
    required this.id,
    required this.scene,
    required this.speakerId,
    required this.speakerName,
    required this.direction,
    required this.text,
    required this.trailingText,
    required this.start,
    required this.end,
    required this.audioSource,
    required this.sourceStart,
    required this.sourceEnd,
    required this.lines,
  });

  factory Segment.fromJson(Map<String, dynamic> json) => Segment(
        id: json['id'] as String,
        scene: json['scene'] as int,
        speakerId: json['speakerId'] as String,
        speakerName: json['speakerName'] as String,
        direction: json['direction'] as String? ?? '',
        text: json['text'] as String,
        trailingText: json['trailingText'] as String?,
        start: Duration(milliseconds: json['startMs'] as int),
        end: Duration(milliseconds: json['endMs'] as int),
        audioSource: json['audioSource'] as String? ?? '',
        sourceStart: Duration(milliseconds: json['sourceStartMs'] as int? ?? 0),
        sourceEnd: Duration(milliseconds: json['sourceEndMs'] as int? ?? 0),
        lines: (json['lines'] as List).map((l) => Line.fromJson(l as Map<String, dynamic>)).toList(),
      );
}

class Line {
  final String text;
  final Duration start;
  final Duration end;

  const Line({required this.text, required this.start, required this.end});

  factory Line.fromJson(Map<String, dynamic> json) => Line(
        text: json['text'] as String,
        start: Duration(milliseconds: json['startMs'] as int),
        end: Duration(milliseconds: json['endMs'] as int),
      );
}
